import{_ as o}from"./chunks/cngal-background-logo.CTvRSuWB.js";import{_ as t,o as r,c as e,a5 as i}from"./chunks/framework.BEZBAInb.js";const g=JSON.parse('{"title":"Konado 소개","description":"","frontmatter":{"title":"Konado 소개","order":1},"headers":[],"relativePath":"ko/2.4/introduction/konado.md","filePath":"ko/2.4/introduction/konado.md","lastUpdated":1788455378000}'),s={name:"ko/2.4/introduction/konado.md"};function n(d,a,h,l,c,p){return r(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="konado-소개" tabindex="-1">Konado 소개 <a class="header-anchor" href="#konado-소개" aria-label="Permalink to &quot;Konado 소개&quot;">​</a></h1><h2 id="프로젝트-개요" tabindex="-1">프로젝트 개요 <a class="header-anchor" href="#프로젝트-개요" aria-label="Permalink to &quot;프로젝트 개요&quot;">​</a></h2><p>Konado는 Godot Engine 기반의 비주얼 노벨 엔진 프레임워크이며, 오픈 소스 커뮤니티가 주도합니다. 우리는 개발자에게 효율적이고 편리한 비주얼 노벨 개발 경험을 제공하고, 창작자가 고품질 비주얼 노벨 작품을 빠르게 구축할 수 있도록 돕는 것을 목표로 합니다. 더 친숙하고 효율적인 도구를 추구하여 게임 창작자가 구현 세부 사항에 매몰되지 않고 스토리텔링과 예술적 표현에 집중할 수 있도록 합니다.</p><h2 id="프로젝트-성과" tabindex="-1">프로젝트 성과 <a class="header-anchor" href="#프로젝트-성과" aria-label="Permalink to &quot;프로젝트 성과&quot;">​</a></h2><ul><li>Konado는 Godot Engine 공식 <a href="https://github.com/godotengine/awesome-godot" target="_blank" rel="noreferrer">awesome-godot</a> 프로젝트의 &quot;Plugins and scripts&quot; 섹션에 추천 플러그인 중 하나로 수록되었습니다.</li><li>Konado는 <a href="https://atomgit.com/GitCode/G-Star100" target="_blank" rel="noreferrer">2025 AtomGit Top 100 Open Source Projects</a>에 선정되었으며, <a href="https://gstar-landscape.gitcode.com/?item=%E9%9F%B3%E8%A7%86%E9%A2%91-%E5%9B%BE%E5%BD%A2-%E6%B8%B8%E6%88%8F-3d--%E6%B8%B8%E6%88%8F%E5%BC%95%E6%93%8E-unity-unreal-godot--konado" target="_blank" rel="noreferrer">AtomGit G-Star Landscape 3.0</a> 생태계 지도에도 포함되었습니다.</li></ul><h2 id="프로젝트-기여자" tabindex="-1">프로젝트 기여자 <a class="header-anchor" href="#프로젝트-기여자" aria-label="Permalink to &quot;프로젝트 기여자&quot;">​</a></h2><p>아래 기여자 차트는 <a href="https://contrib.rocks" target="_blank" rel="noreferrer">contrib.rocks</a>에서 생성되며, 프로젝트 기여자 정보를 실시간으로 업데이트합니다.</p><picture><source media="(prefers-color-scheme: dark)" srcset="https://contrib.rocks/image?repo=godothub/konado&amp;theme=dark"><source media="(prefers-color-scheme: light)" srcset="https://contrib.rocks/image?repo=godothub/konado"><img alt="Contributors" src="https://contrib.rocks/image?repo=godothub/konado"></picture><h2 id="github-star-history" tabindex="-1">GitHub Star History <a class="header-anchor" href="#github-star-history" aria-label="Permalink to &quot;GitHub Star History&quot;">​</a></h2><picture><source media="(prefers-color-scheme: dark)" srcset="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;theme=dark&amp;legend=top-left"><source media="(prefers-color-scheme: light)" srcset="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;legend=top-left"><img alt="Star History Chart" src="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;legend=top-left"></picture><h2 id="atomgit-star-history" tabindex="-1">AtomGit Star History <a class="header-anchor" href="#atomgit-star-history" aria-label="Permalink to &quot;AtomGit Star History&quot;">​</a></h2><p><img src="https://atomgit.com/godothub/konado/starcharts.svg?variant=adaptive" alt="AtomGit Star History"></p><h2 id="후원하기" tabindex="-1">후원하기 <a class="header-anchor" href="#후원하기" aria-label="Permalink to &quot;후원하기&quot;">​</a></h2><p>Konado 프로젝트가 마음에 들고 우리의 작업을 지원하고 싶다면, 다음 방식으로 후원할 수 있습니다.</p><ul><li><a href="https://afdian.com/item/52230b2860a011f083ef52540025c377" target="_blank" rel="noreferrer">Afdian</a></li></ul><h2 id="문의" tabindex="-1">문의 <a class="header-anchor" href="#문의" aria-label="Permalink to &quot;문의&quot;">​</a></h2><p>Konado 프로젝트에 관심이 있다면 QQ 채널 교류 그룹에 참여하여 Konado의 미래 발전 방향을 함께 논의해 주세요.</p><ul><li>QQ 채널 교류 그룹: <a href="https://pd.qq.com/g/godot" target="_blank" rel="noreferrer">https://pd.qq.com/g/godot</a></li></ul><p>문제 피드백이나 기능 제안이 있다면 Konado 프로젝트 <a href="https://github.com/godothub/konado/issues" target="_blank" rel="noreferrer">저장소에 Issue를 제출</a>해 주세요.</p><p>그 외 문의는 <a href="mailto:konado@godothub.com" target="_blank" rel="noreferrer">konado@godothub.com</a>으로 메일을 보내 주세요.</p><h2 id="감사의-말" tabindex="-1">감사의 말 <a class="header-anchor" href="#감사의-말" aria-label="Permalink to &quot;감사의 말&quot;">​</a></h2><p><a href="https://www.cngal.org" target="_blank" rel="noreferrer"><img src="'+o+'" alt="CNGAL"></a></p>',22)])])}const b=t(s,[["render",n]]);export{g as __pageData,b as default};
